/* Tekmilo 1.0 — Blogger theme, no framework or runtime build dependency. */

:root{--blue:#2563eb;--blue-dark:#1e40af;--navy:#0f172a;--bg:#edf3f8;--card:#fff;--text:#172033;--muted:#64748b;--line:#e7eef6;--soft:#f4f8fc;--orange:#f97316;--radius:16px;--shadow:0 3px 15px #1e406b0b;color-scheme:light}

html[data-theme=dark]{--bg:#0b1220;--card:#121e30;--text:#e7eef9;--muted:#a5b5ca;--line:#24344c;--soft:#17263b;--shadow:0 3px 15px #0002;color-scheme:dark}

*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:100px}body{margin:0;color:var(--text);background:radial-gradient(ellipse at 50% 0,#d9e8f4,transparent 70%),var(--bg);font:14px/1.7 'Cairo',Tahoma,Arial,sans-serif}html[lang=en] body{font-family:Inter,Arial,sans-serif}a{color:inherit;text-decoration:none}a:hover{color:var(--blue)}button,input{font:inherit}button,a,input{touch-action:manipulation}button{cursor:pointer}img,svg,video,iframe{max-width:100%}img{height:auto}button,input{min-width:0}button{color:inherit}h1,h2,h3,p{margin:0}h1,h2,h3{line-height:1.4}a,button{transition:color .18s,background .18s,box-shadow .18s}a:focus-visible,button:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid var(--orange);outline-offset:4px}[hidden]{display:none!important}.skip{position:fixed;top:-100px;left:20px;background:var(--card);padding:12px;z-index:100}.skip:focus{top:10px}.sr-only{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.shell{max-width:1180px;margin:12px auto 0;background:var(--card);border-radius:18px 18px 0 0;box-shadow:0 10px 45px #1e406b18;min-height:100vh}.site-header{position:sticky;top:0;z-index:30;display:flex;direction:ltr;align-items:center;gap:18px;padding:14px 22px;background:var(--card);border-radius:18px 18px 0 0;border-bottom:1px solid var(--line)}.brand{display:flex;gap:10px;align-items:center;flex-shrink:0}.brand-mark{width:43px;height:49px;flex-shrink:0}.brand strong{display:block;font:800 21px/1.4 Inter,Tahoma,sans-serif;letter-spacing:-.7px}.brand strong b{color:var(--blue);font-family:Cairo,Tahoma,sans-serif}.brand small{display:block;font-size:7.5px;line-height:1.8;letter-spacing:0;color:var(--muted)}.nav{display:flex;gap:15px;align-items:center;flex:1;justify-content:center;direction:rtl}.nav a{font-size:11px;font-weight:700;white-space:nowrap;padding:13px 0;border-bottom:2px solid transparent}.nav a:hover,.nav a[aria-current=page]{border-color:var(--blue);color:var(--blue)}html[lang=en] .nav{direction:ltr;gap:10px}.header-tools{display:flex;align-items:center;gap:6px}.icon-button{display:inline-flex;align-items:center;justify-content:center;border:0;background:transparent;border-radius:10px;min-width:40px;height:42px;font-size:22px}.icon-button:hover{background:var(--soft)}.language-switch{font-size:11px;font-weight:700;min-height:42px;display:flex;align-items:center;padding:0 4px}.search-toggle{font-size:19px;background:var(--soft);color:var(--blue-dark)}.menu-toggle{display:none}.search-panel{padding:14px 24px;background:var(--soft);border-bottom:1px solid var(--line)}.search-form{display:flex;gap:8px;max-width:620px;margin:auto}.search-form input{width:100%;background:var(--card);border:1px solid var(--line);color:var(--text);border-radius:9px;padding:10px 14px}.button{display:inline-flex;align-items:center;justify-content:center;gap:8px;background:var(--blue);color:#fff;border:1px solid transparent;padding:10px 20px;border-radius:11px;font-weight:700;font-size:13px;min-height:44px}.button:hover{background:var(--blue-dark);color:#fff}.button.secondary{background:var(--card);border:1px solid #b8cfee;color:var(--text)}.button.secondary:hover{border-color:var(--blue);color:var(--blue)}.top-ad{margin:14px auto;max-width:728px}.page-padding{padding:0 18px}.hero{margin:18px 0 14px;position:relative;display:grid;grid-template-columns:1.03fr 1fr;direction:ltr;overflow:hidden;min-height:350px;border-radius:15px;background:radial-gradient(circle at 77% 35%,#b7e1ff 0,transparent 48%),linear-gradient(110deg,#e7f4ff,#f1f8ff 44%,#c7e5ff);color:#0d2846}.hero-copy{padding:30px 0 28px 28px;align-self:center;position:relative;z-index:2;text-align:left}.hero h1{font:800 clamp(24px,2.7vw,37px)/1.15 Inter,Arial,sans-serif;letter-spacing:-1px}.hero h1 span{display:block;color:#0560ff}.hero-ar{font-size:25px;font-weight:800;margin:8px 0 5px;direction:rtl;text-align:left}.hero-tagline{font-size:14px;font-weight:700;direction:ltr}.hero-description{font-size:14px;color:#526784;max-width:460px;margin:13px 0 18px;line-height:1.9;direction:rtl;text-align:left}html[lang=en] .hero-description{direction:ltr}.hero-actions{display:flex;gap:12px;direction:rtl;justify-content:flex-end}.hero-art{align-self:stretch;display:flex;align-items:center;min-width:0}.hero-art svg{width:100%;height:auto;overflow:visible}.content-layout{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:17px;direction:ltr;align-items:start}.main-column,.sidebar{min-width:0;direction:rtl}html[lang=en] .main-column,html[lang=en] .sidebar{direction:ltr}.panel{border:1px solid var(--line);border-radius:var(--radius);padding:16px;background:var(--card);box-shadow:var(--shadow);margin-bottom:14px}.section-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:13px}.section-heading h2{font-size:18px;font-weight:800}.section-heading>a{font-size:12px;font-weight:700;color:var(--blue);min-height:30px;display:flex;align-items:center}.featured-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;direction:ltr}.post-card{min-width:0;border-radius:12px;overflow:hidden;background:var(--card);border:1px solid var(--line);direction:rtl;box-shadow:var(--shadow);position:relative}.post-card a{display:block;height:100%}.post-media{position:relative;aspect-ratio:16/10;background:linear-gradient(135deg,#d9edff,#b6d8f9);overflow:hidden}.post-media img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .25s}.post-card:hover .post-media img{transform:scale(1.025)}.image-fallback{display:grid;place-content:center;color:#3371a6;font:800 22px Inter,Arial;height:100%;min-height:100px;background:linear-gradient(140deg,#d5ecff,#9fcff3);letter-spacing:-1px}.badge{position:absolute;inset:9px 8px auto auto;background:var(--blue);color:#fff;border-radius:7px;padding:3px 9px;font-size:10px;font-weight:700;max-width:calc(100% - 16px);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.card-body{padding:11px}.post-card h3{font-size:13px;font-weight:800;line-height:1.7}.excerpt{font-size:11px;line-height:1.8;color:var(--muted);margin-top:6px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.post-meta{font-size:10px;color:var(--muted);display:flex;align-items:center;gap:6px;margin-top:9px}.post-meta time{unicode-bidi:plaintext}.featured-grid>.post-card:first-child{grid-row:span 3;border:0;min-height:310px}.featured-grid>.post-card:first-child .post-media{height:100%;aspect-ratio:auto;position:absolute;inset:0}.featured-grid>.post-card:first-child .post-media:after{content:'';position:absolute;inset:0;background:linear-gradient(transparent 20%,#061924f2)}.featured-grid>.post-card:first-child .card-body{position:absolute;inset:auto 0 0;color:#fff;padding:20px}.featured-grid>.post-card:first-child h3{font-size:18px}.featured-grid>.post-card:first-child .post-meta{color:#d9e9f7}.featured-grid>.post-card:first-child .badge{z-index:2}.featured-grid>.post-card:not(:first-child)>a{display:grid;grid-template-columns:41% 59%;direction:ltr}.featured-grid>.post-card:not(:first-child) .post-media{aspect-ratio:auto;min-height:92px;height:100%}.featured-grid>.post-card:not(:first-child) .card-body{padding:8px 10px;direction:rtl}.featured-grid .excerpt{display:none}html[lang=en] .post-card,html[lang=en] .featured-grid>.post-card:not(:first-child) .card-body{direction:ltr}.category-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;direction:ltr}.category-card{display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;min-height:125px;border-radius:12px;padding:12px 5px;color:#fff;box-shadow:inset 0 1px 0 #ffffff50;background:linear-gradient(130deg,var(--cat-a),var(--cat-b));transition:transform .2s}.category-card:hover{color:#fff;transform:translateY(-3px)}.category-card svg{width:35px;height:35px;margin-bottom:10px}.category-card strong{font-size:11px}.category-card small{font:600 10px/1.5 Inter,Arial;margin-top:2px}.article-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.reviews-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.empty-state{padding:24px 14px;text-align:center;color:var(--muted);font-size:13px;background:var(--soft);border-radius:10px;grid-column:1/-1}.empty-state a{color:var(--blue);text-decoration:underline}.pagination{display:flex;justify-content:space-between;gap:12px;padding:20px 0 4px;flex-wrap:wrap}.pagination a{background:var(--soft);border:1px solid var(--line);padding:8px 14px;border-radius:9px;font-size:12px;font-weight:700}.sidebar .panel{padding:16px 13px}.sidebar h2{font-size:15px}.social-links{display:flex;gap:8px;flex-wrap:wrap;justify-content:center}.social-links a{display:grid;place-content:center;min-width:36px;min-height:36px;background:var(--soft);color:var(--blue);border-radius:8px;font-weight:800;font-size:12px}.social-links a:hover{background:var(--blue);color:#fff}.newsletter h2{font-size:17px}.newsletter p{font-size:12px;line-height:1.8;margin:8px 0 13px}.newsletter-form{display:flex;gap:8px}.newsletter-form input[type=email]{width:100%;min-width:0;padding:10px 12px;background:var(--card);color:var(--text);border:1px solid var(--line);border-radius:9px}.sidebar .newsletter-form{flex-direction:column}.newsletter-footer{margin-top:6px;padding:21px 28px;color:#fff;background:linear-gradient(125deg,#032439,#064576);border:4px solid var(--card);border-radius:16px;display:grid;grid-template-columns:1fr 1fr;gap:20px;align-items:center}.newsletter-footer p{margin:5px 0 0;color:#d3e7f8}.popular-list{list-style:none;padding:0;margin:0;counter-reset:popular}.popular-list li{counter-increment:popular;position:relative;margin:0 0 14px}.popular-list a{display:flex;gap:9px;align-items:center;font-size:11px;font-weight:700;line-height:1.7}.popular-list a:before{content:counter(popular);flex:0 0 21px;height:22px;display:grid;place-content:center;border-radius:6px;background:#ff8b00;color:#fff;font:700 12px Inter}.popular-list img{width:46px;height:46px;object-fit:cover;border-radius:7px;flex-shrink:0}.popular-list .image-fallback{min-height:46px;width:46px;font-size:11px;border-radius:7px;flex-shrink:0}.ad-slot{display:none;max-width:100%;overflow:hidden;text-align:center;margin-bottom:14px;border-radius:10px;min-width:0}.ad-slot:has(.ad-content){display:block}.ad-content{max-width:100%;overflow:hidden;min-height:90px;background:var(--soft)}.ad-content:before{content:'إعلان · Advertisement';display:block;font-size:9px;color:var(--muted);padding:3px}.ad-slot[data-slot=sidebarRectangle] .ad-content{min-height:250px}.ad-slot[data-slot=sidebarVertical] .ad-content{min-height:600px}.ad-slot[data-slot=mid] .ad-content{min-height:250px}.ad-slot[data-slot=footer] .ad-content{min-height:250px}.ad-content iframe{max-width:100%}.ad-placeholder{display:none}.design-preview .ad-slot{display:block}.design-preview .ad-placeholder{display:grid;place-content:center;min-height:90px;background:repeating-linear-gradient(135deg,#053452 0 80px,#064b78 80px 140px,#043b60 140px 200px);color:#fff;border-radius:9px;padding:14px}.design-preview .ad-slot:has(.ad-content) .ad-placeholder{display:none}.ad-placeholder strong{font-size:18px}.ad-placeholder small{font-size:11px}.design-preview .sidebar .ad-placeholder,.design-preview .footer-ad .ad-placeholder{background:linear-gradient(130deg,#c6e5ff,#b0dafb);color:#0d3356;min-height:250px}.design-preview [data-slot=sidebarVertical] .ad-placeholder{min-height:390px}.design-preview .ad-placeholder .ad-icon{font-size:36px;opacity:.35;margin-bottom:10px}.preview-notice{display:none;text-align:center;font-size:11px;padding:8px;background:#fff1d6;color:#693e00}.design-preview .preview-notice{display:block}.site-footer{padding:26px 26px 12px;background:linear-gradient(110deg,#0b1923,#0d2534);color:#dae7ef}.footer-grid{display:grid;grid-template-columns:1.6fr .8fr .8fr 1.1fr;gap:28px;direction:ltr}.footer-grid>div{direction:rtl}.footer-grid>div:first-child{direction:ltr}.site-footer .brand small{color:#c0cfda}.site-footer .brand strong b{color:#fff}.footer-description{font-size:11px;line-height:1.9;margin:12px 0;text-align:right;max-width:300px}.footer-grid h2{font-size:14px;margin-bottom:11px}.footer-links{display:grid;gap:7px;font-size:11px}.site-footer a:hover{color:#86baff}.site-footer .social-links{justify-content:flex-start}.site-footer .social-links a{background:#14394d;color:#dceeff;min-width:28px;min-height:28px}.copyright{margin-top:20px;padding-top:13px;text-align:center;border-top:1px solid #29404f;font-size:10px;color:#b6c7d4}.footer-ad{margin:0}.footer-grid:not(:has(.ad-content)):not(:has(.ad-placeholder:not([hidden]))){grid-template-columns:1.6fr 1fr 1fr}.article-page{padding:24px}.breadcrumbs{display:flex;gap:8px;flex-wrap:wrap;color:var(--muted);font-size:12px;margin-bottom:18px}.article-title{font-size:clamp(26px,3.5vw,40px);font-weight:800;line-height:1.55;overflow-wrap:anywhere}.article-info{display:flex;flex-wrap:wrap;gap:14px;color:var(--muted);font-size:12px;margin:14px 0 22px}.article-cover{width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:12px;margin-bottom:20px}.article-body{font-size:17px;line-height:2.1;overflow-wrap:anywhere}.article-body p{margin:0 0 1.3em}.article-body h2{font-size:27px;margin:1.5em 0 .7em}.article-body h3{font-size:22px;margin:1.4em 0 .6em}.article-body a{color:var(--blue);text-decoration:underline;text-underline-offset:3px}.article-body img{max-width:100%!important;height:auto!important;border-radius:9px}.article-body .separator{max-width:100%}.article-body .separator a{margin-inline:0!important}.article-body iframe{max-width:100%}.article-body blockquote{margin:24px 0;border-inline-start:4px solid var(--blue);padding:15px 20px;background:var(--soft);border-radius:8px}.article-body pre{direction:ltr;text-align:left;background:#0d1b2c;color:#e2edff;padding:20px;border-radius:12px;overflow:auto;max-width:100%;font-size:13px;line-height:1.8}.article-body code{font-family:Consolas,monospace}.table-scroll{overflow-x:auto;max-width:100%;margin:24px 0}.article-body table{border-collapse:collapse;width:100%}.article-body th,.article-body td{padding:10px;border:1px solid var(--line);text-align:start}.article-body th{background:var(--soft)}.toc{padding:16px 20px;border:1px solid var(--line);background:var(--soft);border-radius:12px;margin-bottom:24px}.toc summary{cursor:pointer;font-weight:800}.toc ol{padding-inline-start:23px;margin-bottom:0;font-size:13px;line-height:2}.toc li.subheading{margin-inline-start:15px}.article-labels{display:flex;gap:8px;flex-wrap:wrap;margin:25px 0}.article-labels a{background:var(--soft);padding:5px 12px;border-radius:20px;font-size:12px}.share-bar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;border-block:1px solid var(--line);padding:18px 0;margin:20px 0}.share-bar button{background:var(--soft);border:1px solid var(--line);border-radius:8px;padding:8px 14px;font-size:12px;min-height:44px}.translation-link{color:var(--blue);font-size:13px}.comment-list{padding:0;list-style:none}.comment-list li{padding:18px 0;border-bottom:1px solid var(--line)}.comment-list time{font-size:11px;color:var(--muted)}.comment-body{overflow-wrap:anywhere;margin-top:7px}.comments h2{font-size:20px;margin:25px 0 15px}.comments .button{margin:16px 0}.related-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.error-page{text-align:center;padding:70px 20px}.error-page strong{font:800 80px Inter;color:var(--blue)}.error-page p{color:var(--muted);margin:15px 0 25px}.static-page .article-info,.static-page .share-bar{display:none}.layout-only{display:none}html[data-theme=dark] .hero{background:radial-gradient(circle at 77% 35%,#174666,transparent 50%),linear-gradient(110deg,#172c44,#112b45);color:#e6f2ff}html[data-theme=dark] .hero-description{color:#b9cee4}html[data-theme=dark] body{background:var(--bg)}html[data-theme=dark] .hero h1 span{color:#65a1ff}html[lang=en] .footer-grid>div{direction:ltr}html[lang=en] .footer-description{text-align:left}

.ad-slot.top-ad{width:728px;max-width:calc(100% - 36px);margin:14px auto}.ad-placeholder .ad-icon{display:none}.sidebar .ad-placeholder .ad-icon,.footer-ad .ad-placeholder .ad-icon{display:block}.post-media .badge~.badge{display:none}.footer-grid{grid-template-columns:1.6fr 1fr 1fr}.footer-grid:has(.ad-content),.design-preview .footer-grid{grid-template-columns:1.6fr .8fr .8fr 1.1fr}.archive-title{font-size:21px}

@media(min-width:1400px){.shell{margin-top:24px}}

@media(max-width:1150px){.site-header{gap:12px;padding:12px 17px}.brand strong{font-size:18px}.brand-mark{width:34px}.nav{gap:11px}.nav a{font-size:10px}.content-layout{grid-template-columns:minmax(0,1fr) 235px;gap:12px}.panel{padding:12px}.hero h1{font-size:31px}.hero-ar{font-size:22px}.category-grid{gap:7px}.category-card strong{font-size:10px}.article-grid{gap:8px}.post-card h3{font-size:12px}.header-tools{gap:1px}}

@media(max-width:950px){.shell{margin:0;border-radius:0}.site-header{border-radius:0;flex-wrap:wrap}.menu-toggle{display:inline-flex}.header-tools{margin-left:auto}.nav{display:none;flex-basis:100%;order:3;flex-wrap:wrap;justify-content:flex-start;gap:8px 20px;border-top:1px solid var(--line);padding-top:10px}.nav.is-open{display:flex}.nav a{font-size:13px;min-height:44px;padding:10px 6px}.hero{min-height:300px}.hero-copy{padding:25px 0 25px 22px}.hero h1{font-size:27px}.hero-ar{font-size:20px}.hero-description{font-size:12px}.content-layout{grid-template-columns:minmax(0,1fr) 210px}.featured-grid{grid-template-columns:1fr}.featured-grid>.post-card:first-child{grid-row:auto;min-height:270px}.featured-grid>.post-card:not(:first-child) .post-media{min-height:90px}.article-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.category-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.category-card{min-height:110px}.reviews-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.footer-grid{grid-template-columns:1.3fr 1fr 1fr}.footer-ad{grid-column:1/-1}.footer-description{max-width:none}.newsletter-footer{grid-template-columns:1fr;gap:12px}.top-ad{margin-inline:18px}}

@media(max-width:700px){.page-padding{padding:0 12px}.site-header{padding:10px 12px;gap:5px}.brand strong{font-size:17px}.brand-mark{width:30px;height:38px}.brand small{font-size:6px}.icon-button{min-width:38px;height:42px}.language-switch{font-size:10px}.hero{grid-template-columns:1fr;min-height:0;margin-top:12px}.hero-copy{padding:26px 23px 0}.hero h1{font-size:31px}.hero-ar{font-size:22px}.hero-description{font-size:13px;max-width:none}.hero-art{justify-content:center;height:250px}.hero-art svg{width:380px;height:250px}.hero-actions{justify-content:flex-end;flex-wrap:wrap}.content-layout{grid-template-columns:1fr}.sidebar{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.sidebar>.panel{margin:0}.sidebar>.ad-slot{grid-column:1/-1}.sidebar>.popular-panel{grid-column:1/-1}.featured-grid{grid-template-columns:1fr 1fr;gap:10px}.featured-grid>.post-card:first-child{grid-row:span 3;min-height:315px}.featured-grid>.post-card:not(:first-child)>a{display:block}.featured-grid>.post-card:not(:first-child) .post-media{display:none}.featured-grid>.post-card:first-child h3{font-size:16px}.featured-grid>.post-card:not(:first-child) .card-body{padding:10px}.featured-grid .post-card h3{font-size:12px}.reviews-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.post-card h3{font-size:13px}.section-heading h2{font-size:17px}.newsletter-footer{margin-top:14px;padding:18px}.footer-grid{grid-template-columns:1fr 1fr;gap:24px}.footer-grid>div:first-child{grid-column:1/-1}.site-footer{padding:24px 20px 14px}.related-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.article-page{padding:18px}.article-body{font-size:16px}.article-body h2{font-size:23px}.article-body h3{font-size:20px}.top-ad{margin-inline:12px}.ad-slot[data-slot=sidebarVertical] .ad-content{min-height:250px}}

@media(max-width:400px){.brand small{display:none}.brand strong{font-size:15px}.brand{gap:6px}.site-header{gap:0}.hero h1{font-size:27px}.hero-ar{font-size:20px}.hero-copy{padding:23px 18px 0}.hero-tagline{font-size:11px}.hero-actions{gap:8px}.hero-actions .button{padding:9px 12px;font-size:12px}.reviews-grid{grid-template-columns:1fr}.reviews-grid .post-card>a{display:grid;grid-template-columns:40% 60%;direction:ltr}.reviews-grid .post-media{height:100%;aspect-ratio:auto}.sidebar{grid-template-columns:1fr}.featured-grid>.post-card:first-child{min-height:340px}.newsletter-form{flex-direction:column}.category-card small{font-size:9px}.section-heading h2{font-size:16px}}

@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{transition:none!important;animation:none!important}}

@media print{.site-header,.sidebar,.ad-slot,.hero,.site-footer,.newsletter-footer,.share-bar,.pagination,.related-panel,.comments{display:none!important}.shell{box-shadow:none;max-width:none}.content-layout{display:block}.article-page{border:0}.article-body{font-size:12pt}body{background:#fff;color:#000}}



/* Premium visual pass: mirrors the magazine proportions of the approved reference. */

:root{--blue:#0869f2;--blue-dark:#064fc4;--navy:#082b45;--radius:14px;--shadow:0 5px 18px rgba(18,69,108,.08)}

body{background:linear-gradient(180deg,#e6f0f7 0,#f7fbff 350px,var(--bg) 850px)}

.shell{max-width:1190px;margin-top:8px;border:1px solid rgba(184,207,227,.72);box-shadow:0 18px 60px rgba(29,72,110,.15)}

.site-header{min-height:72px;padding:10px 27px;gap:25px;background:rgba(255,255,255,.94);backdrop-filter:blur(16px)}

.brand{gap:11px}.brand-mark{width:39px;height:46px}.brand strong{font-size:20px;line-height:1.15}.brand small{margin-top:3px;font-size:7px;font-weight:600}

.nav{gap:16px}.nav a{font-size:11px;padding:20px 0 17px}.nav a:hover,.nav a[aria-current=page]{border-color:var(--blue);color:var(--blue)}

.header-tools{gap:5px}.icon-button{width:38px;min-width:38px;height:38px;border-radius:10px;font-size:19px}.search-toggle{box-shadow:inset 0 0 0 1px #dbe8f5}.language-switch{font-size:10px;color:#364a60;padding-inline:5px}.menu-toggle{font-size:22px}

.search-panel{padding:12px 24px;background:#f4f9fd;box-shadow:inset 0 1px var(--line)}.search-form{max-width:680px}.search-form input{height:42px;border-radius:12px;box-shadow:0 2px 7px rgba(15,54,86,.04)}

.page-padding{padding:0 20px}.ad-slot.top-ad{width:min(728px,calc(100% - 40px));margin:14px auto 12px}.top-ad .ad-placeholder{min-height:90px}

.hero{margin:13px 0 17px;min-height:338px;border-radius:14px;background:radial-gradient(circle at 77% 32%,#c4eaff 0 4%,transparent 4.2%),radial-gradient(circle at 89% 70%,#61bdf5 0 3%,transparent 3.2%),radial-gradient(circle at 72% 42%,#cceaff 0,transparent 47%),linear-gradient(110deg,#edf8ff 0%,#edf8ff 38%,#d9f0ff 100%);box-shadow:inset 0 0 0 1px rgba(136,205,247,.28)}

.hero:before{content:'';position:absolute;inset:0;pointer-events:none;background:linear-gradient(135deg,transparent 35%,rgba(255,255,255,.38) 35% 42%,transparent 42% 52%,rgba(255,255,255,.32) 52% 57%,transparent 57%)}

.hero-copy{padding:35px 0 34px 34px}.hero h1{font-size:35px;letter-spacing:-1.5px}.hero-ar{font-size:24px;margin-top:8px}.hero-tagline{font-size:13px;color:#183854}.hero-description{max-width:430px;font-size:13px;color:#58708a;margin:12px 0 20px}.hero-actions{gap:10px}.button{border-radius:9px;min-height:40px;padding:9px 17px;font-size:12px;box-shadow:0 3px 7px rgba(8,105,242,.15)}.button.secondary{box-shadow:none;background:rgba(255,255,255,.78)}

.content-layout{grid-template-columns:minmax(0,1fr) 300px;gap:18px}.panel{border-color:#e9f0f6;border-radius:13px;padding:14px;background:linear-gradient(180deg,#fff,#fdfefe);box-shadow:0 4px 13px rgba(19,67,104,.06);margin-bottom:16px}.section-heading{margin:0 2px 13px}.section-heading h2{font-size:17px;letter-spacing:-.25px}.section-heading>a{font-size:11px;color:#0873ef}

.featured-grid{gap:10px}.post-card{border-color:#e6edf4;border-radius:10px;box-shadow:0 3px 10px rgba(18,65,101,.055)}.featured-grid>.post-card:first-child{min-height:320px}.featured-grid>.post-card:first-child .card-body{padding:19px}.featured-grid>.post-card:first-child h3{font-size:17px;line-height:1.65}.featured-grid>.post-card:not(:first-child)>a{grid-template-columns:43% 57%}.featured-grid>.post-card:not(:first-child) .post-media{min-height:96px}.featured-grid>.post-card:not(:first-child) .card-body{padding:9px 11px}.featured-grid>.post-card:not(:first-child) h3{font-size:12px}.badge{inset:8px 8px auto auto;padding:3px 8px;border-radius:6px;background:linear-gradient(135deg,#1181fb,#0662df);font-size:9px;box-shadow:0 3px 8px rgba(0,85,201,.28)}

.category-grid{gap:8px}.category-card{position:relative;isolation:isolate;min-height:118px;border-radius:10px;padding:13px 4px 10px;overflow:hidden;box-shadow:0 6px 13px rgba(12,50,91,.13),inset 0 1px rgba(255,255,255,.42)}.category-card:before{content:'';position:absolute;width:90px;height:90px;top:-48px;right:-35px;z-index:-1;border-radius:50%;background:rgba(255,255,255,.14)}.category-card:after{content:'';position:absolute;width:58px;height:58px;bottom:-35px;left:-24px;z-index:-1;border-radius:50%;border:1px solid rgba(255,255,255,.18)}.category-card svg{width:32px;height:32px;margin-bottom:7px;filter:drop-shadow(0 2px 3px rgba(0,0,0,.14))}.category-card strong{font-size:10px;line-height:1.45}.category-card small{font-size:8.5px;opacity:.94}

.article-grid{gap:10px}.article-grid .post-card h3,.reviews-grid .post-card h3{font-size:12px;line-height:1.6}.article-grid .card-body,.reviews-grid .card-body{padding:10px}.article-grid .post-media{aspect-ratio:1.4/1}.excerpt{font-size:10px;line-height:1.75}.post-meta{font-size:9px;margin-top:7px}

.sidebar{gap:14px}.sidebar .panel{padding:15px 14px}.sidebar h2{font-size:14px}.social-links{gap:7px}.social-links a{width:35px;min-width:35px;height:35px;min-height:35px;color:#fff;background:linear-gradient(135deg,#1687ff,#0563d8);box-shadow:0 3px 8px rgba(8,99,216,.19)}.social-links a:nth-child(2n){background:linear-gradient(135deg,#252a35,#06080d)}.social-links a:nth-child(3n){background:linear-gradient(135deg,#ff5d5d,#e21b29)}.social-links a:nth-child(4n){background:linear-gradient(135deg,#b34aff,#ef4a94)}.social-links a:nth-child(5n){background:linear-gradient(135deg,#27c3f3,#1686c8)}

.newsletter{position:relative;overflow:hidden}.newsletter:before{content:'✉';position:absolute;left:14px;top:12px;color:#1782f7;font-size:18px;opacity:.85}.newsletter h2{padding-inline-start:27px;font-size:16px}.newsletter p{font-size:11px;color:var(--muted)}.sidebar .newsletter-form input[type=email]{height:37px;padding:8px 11px;background:#f7fbff}.sidebar .newsletter-form .button{height:38px;min-height:38px}.popular-list li{margin-bottom:11px}.popular-list a{font-size:10px}.popular-list a:before{width:20px;height:21px;background:linear-gradient(135deg,#ff9f17,#ef6f00)}.popular-list img{width:43px;height:43px}

.ad-slot{border-radius:11px}.design-preview .ad-placeholder{min-height:90px;background:linear-gradient(124deg,#032d50 0%,#075384 47%,#062d50 100%);position:relative;overflow:hidden;box-shadow:inset 0 0 0 1px rgba(143,207,255,.19)}.design-preview .ad-placeholder:before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(135deg,rgba(88,179,239,.15) 0 55px,transparent 55px 130px);pointer-events:none}.design-preview .ad-placeholder strong,.design-preview .ad-placeholder small{position:relative}.design-preview .ad-placeholder strong{font-size:16px;text-shadow:0 2px 4px #001c32}.design-preview .ad-placeholder small{font-size:10px}.design-preview .sidebar .ad-placeholder,.design-preview .footer-ad .ad-placeholder{min-height:250px;background:linear-gradient(145deg,#d9efff,#b5dafe);color:#12416c}.design-preview .sidebar .ad-placeholder:before,.design-preview .footer-ad .ad-placeholder:before{background:radial-gradient(circle at 80% 15%,rgba(255,255,255,.65),transparent 31%),linear-gradient(135deg,transparent 42%,rgba(94,166,222,.2) 42% 57%,transparent 57%)}.design-preview [data-slot=sidebarVertical] .ad-placeholder{min-height:440px}.design-preview .ad-placeholder .ad-icon{font-size:39px}.ad-content{border-radius:11px}.ad-content:before{padding:5px;font-size:8px}.preview-notice{padding:6px}

.newsletter-footer{margin:2px 20px 0;padding:18px 28px;border:0;border-radius:13px;background:linear-gradient(115deg,#032840,#07537d 55%,#032d50);box-shadow:0 8px 18px rgba(0,39,67,.14)}.newsletter-footer:before{content:'';position:absolute}.newsletter-footer h2{font-size:19px}.newsletter-footer p{font-size:11px}.newsletter-footer .newsletter-form{justify-content:flex-end}.newsletter-footer .newsletter-form input{height:40px}.newsletter-footer .button{min-width:105px}

.site-footer{margin-top:12px;padding:28px 30px 14px;background:linear-gradient(125deg,#061c29,#082a3d 54%,#061d2b)}.footer-grid{gap:34px}.footer-description{font-size:10px;max-width:280px}.footer-grid h2{font-size:13px}.footer-links{font-size:10px;gap:8px}.copyright{margin-top:18px}

.legacy-layout-slot,#SidebarExtras{display:none!important}

html[data-theme=dark] body{background:linear-gradient(180deg,#101c2b,#0b1220 420px)}html[data-theme=dark] .site-header{background:rgba(18,30,48,.94)}html[data-theme=dark] .panel{background:linear-gradient(180deg,#121e30,#101a2a)}html[data-theme=dark] .search-panel{background:#101c2c}html[data-theme=dark] .hero{background:radial-gradient(circle at 77% 32%,#164d70 0 4%,transparent 4.2%),linear-gradient(110deg,#132b43,#0c243e)}html[data-theme=dark] .hero:before{background:linear-gradient(135deg,transparent 35%,rgba(109,180,224,.12) 35% 42%,transparent 42% 52%,rgba(109,180,224,.08) 52% 57%,transparent 57%)}html[data-theme=dark] .hero-tagline{color:#afcce5}html[data-theme=dark] .language-switch{color:#d9e8f8}html[data-theme=dark] .category-card{box-shadow:0 6px 13px #0004,inset 0 1px #ffffff30}

body#layout{--ink:#0f2a43;--muted:#5d7388;--bd:#d6e3f0;--paper:#fff;--accent:#0b6bd9;--tint:#eaf3ff;--soft:#f6f9fd;margin:0!important;padding:30px 18px 96px!important;color:var(--ink)!important;background:radial-gradient(900px 340px at 85% -80px,#d7e9fb,transparent 70%),radial-gradient(700px 300px at 5% -60px,#fde9cf,transparent 70%),#eef4fa!important;font:14px/1.7 'Cairo',Tahoma,Arial,sans-serif!important;direction:rtl!important;text-align:right!important;min-width:0!important}

body#layout *,body#layout *:before,body#layout *:after{box-sizing:border-box!important}

body#layout a{text-decoration:none!important}

body#layout .skip,body#layout .site-header,body#layout .search-panel,body#layout .preview-notice,body#layout .hero,body#layout .ad-placeholder,body#layout .newsletter,body#layout .newsletter-footer,body#layout .copyright,body#layout .footer-grid>div:not(.footer-ad),body#layout .panel:not(:has(.section)),body#layout noscript{display:none!important}

body#layout .shell{max-width:1060px!important;min-height:0!important;margin:0 auto!important;border:0!important;border-radius:0!important;background:transparent!important;box-shadow:none!important}

body#layout .page-padding{padding:0!important}

body#layout .site-footer{margin:0!important;padding:0!important;background:none!important;color:inherit!important}

body#layout .footer-grid{display:block!important;margin:0!important}

body#layout .footer-ad{margin:0!important}

body#layout .panel{margin:0!important;padding:0!important;border:0!important;border-radius:0!important;background:none!important;box-shadow:none!important}

body#layout .layout-only{display:block!important;max-width:1060px!important;margin:0 auto 14px!important}

body#layout .tekmilo-layout-controls:before{content:'Tekmilo · لوحة تنسيق القالب'!important;display:block!important;margin:0 0 14px!important;padding:22px 26px!important;border-radius:18px!important;color:#fff!important;font:800 22px/1.4 'Cairo',Tahoma,sans-serif!important;background:radial-gradient(circle at 12% 0,rgba(255,255,255,.22),transparent 38%),linear-gradient(120deg,#032840,#0869f2 70%,#35a7ff)!important;box-shadow:0 14px 32px rgba(8,80,170,.25)!important}

body#layout .shell:before{content:'دليل الألوان   🟧 مساحات إعلانية   🟦 مناطق إضافات مرنة   🟩 أقسام القالب الأساسية   ⬜ أدوات قديمة للمراجعة'!important;display:block!important;margin:0 0 16px!important;padding:11px 18px!important;border:1px solid var(--bd)!important;border-radius:12px!important;background:var(--paper)!important;color:var(--muted)!important;font:700 12px/1.8 'Cairo',Tahoma,sans-serif!important;box-shadow:0 3px 10px rgba(15,60,100,.05)!important}

body#layout .content-layout{display:grid!important;grid-template-columns:minmax(0,1fr) 330px!important;gap:16px!important;direction:ltr!important;align-items:start!important;margin:0!important}

body#layout .main-column,body#layout .sidebar{display:block!important;min-width:0!important;direction:rtl!important}

body#layout .ad-slot,body#layout .ad-slot.top-ad{display:block!important;width:auto!important;max-width:none!important;margin:0!important;overflow:visible!important;border-radius:0!important;background:none!important}

body#layout .section{position:relative!important;min-height:0!important;margin:0 0 14px!important;padding:50px 14px 14px!important;overflow:hidden!important;border:1px solid var(--bd)!important;border-radius:16px!important;background:var(--paper)!important;box-shadow:0 6px 20px rgba(15,60,100,.07)!important;transition:box-shadow .2s,border-color .2s!important}

body#layout .section:hover{border-color:var(--accent)!important;box-shadow:0 10px 28px rgba(15,60,100,.13)!important}

body#layout .section:before{position:absolute!important;top:0!important;right:0!important;left:0!important;height:38px!important;display:flex!important;align-items:center!important;padding:0 16px!important;color:var(--accent)!important;background:var(--tint)!important;border-bottom:1px solid var(--bd)!important;font:800 12px/1 'Cairo',Tahoma,sans-serif!important;white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important}

body#layout .section .widget{min-height:0!important;margin:0 0 10px!important;padding:0!important;overflow:hidden!important;border:1px solid var(--bd)!important;border-radius:12px!important;background:var(--soft)!important;box-shadow:none!important}

body#layout .section .widget:last-of-type{margin-bottom:0!important}

body#layout .section .widget .widget-content{min-height:0!important;padding:12px 14px!important;background:transparent!important}

body#layout .section .widget h2,body#layout .section .widget h3,body#layout .section .widget h4,body#layout .section .widget .layout-widget-title,body#layout .section .widget .layout-title{margin:0!important;color:var(--ink)!important;font:800 13px/1.7 'Cairo',Tahoma,sans-serif!important}

body#layout .section .widget .layout-widget-description,body#layout .section .widget .widget-description{color:var(--muted)!important;font-size:12px!important}

body#layout .section .widget a.editlink,body#layout .section .widget .editlink{display:inline-flex!important;align-items:center!important;padding:3px 11px!important;border-radius:999px!important;background:var(--tint)!important;color:var(--accent)!important;font:800 11px/1.6 'Cairo',Tahoma,sans-serif!important}

body#layout .section .widget a.editlink:hover{background:var(--accent)!important;color:#fff!important}

body#layout .section .add_widget,body#layout .section .addwidget{margin:10px 0 0!important;padding:10px!important;border:1px dashed var(--bd)!important;border-radius:12px!important;background:var(--paper)!important;text-align:center!important}

body#layout .section .add_widget a,body#layout .section .addwidget a{display:inline-flex!important;align-items:center!important;gap:7px!important;padding:9px 18px!important;border-radius:10px!important;background:linear-gradient(135deg,#1687ff,#0563d8)!important;color:#fff!important;font:800 12px/1.5 'Cairo',Tahoma,sans-serif!important;box-shadow:0 4px 10px rgba(8,99,216,.25)!important;transition:transform .15s,box-shadow .15s!important}

body#layout .section .add_widget a:hover,body#layout .section .addwidget a:hover{transform:translateY(-1px)!important;box-shadow:0 7px 14px rgba(8,99,216,.32)!important}

body#layout #Configuration{--accent:#6d28d9;--tint:#f3ecff;--bd:#d9c8f7;border:2px solid #8b5cf6!important;background:linear-gradient(135deg,#faf6ff,#fff)!important}

body#layout #Configuration:before{content:'⚙  الإعدادات الرئيسية · JSON لروابط التواصل والصفحات والنشرة والشعار'!important}

body#layout #Adtop,body#layout #Admid,body#layout #Adinfeed,body#layout #Adarticle,body#layout #AdsidebarRectangle,body#layout #AdsidebarVertical,body#layout #Adfooter{--accent:#c2410c;--tint:#fff3e2;--bd:#f5d7ae;border-inline-start:5px solid #f97316!important}

body#layout #Adtop .widget,body#layout #Admid .widget,body#layout #Adinfeed .widget,body#layout #Adarticle .widget,body#layout #AdsidebarRectangle .widget,body#layout #AdsidebarVertical .widget,body#layout #Adfooter .widget{border-style:dashed!important;background:#fffaf3!important}

body#layout #Adtop:after,body#layout #Admid:after,body#layout #Adinfeed:after,body#layout #Adarticle:after,body#layout #AdsidebarRectangle:after,body#layout #AdsidebarVertical:after,body#layout #Adfooter:after{display:grid!important;place-items:center!important;margin:14px auto 2px!important;border-radius:8px!important;border:1px solid #f3b872!important;color:#9a3412!important;direction:ltr!important;unicode-bidi:isolate!important;font:800 12px/1.4 Inter,Arial,sans-serif!important;letter-spacing:.2px!important;text-align:center!important;white-space:pre!important;background:repeating-linear-gradient(135deg,#ffedd5 0 14px,#fed7aa 14px 28px)!important}

body#layout #Adtop:before{content:'▧  إعلان · أعلى كل الصفحات   |   \2066 728 × 90\2069'!important}

body#layout #Adtop:after{content:'728 × 90\A Leaderboard'!important;width:min(100%,520px)!important;aspect-ratio:728/90!important;min-height:64px!important}

body#layout #Admid:before{content:'▧  إعلان · بين أقسام الصفحة الرئيسية   |   \2066 970 × 250\2069'!important}

body#layout #Admid:after{content:'970 × 250\A Billboard'!important;width:min(100%,480px)!important;aspect-ratio:970/250!important}

body#layout #Adinfeed:before{content:'▧  إعلان · داخل قائمة المقالات   |   متجاوب'!important}

body#layout #Adinfeed:after{content:'Responsive\A In-feed'!important;width:min(100%,420px)!important;aspect-ratio:3/1!important}

body#layout #Adarticle:before{content:'▧  إعلان · نهاية صفحة المقال   |   متجاوب'!important}

body#layout #Adarticle:after{content:'Responsive\A In-article'!important;width:min(100%,420px)!important;aspect-ratio:3/1!important}

body#layout #AdsidebarRectangle:before{content:'▧  إعلان · الشريط الجانبي   |   \2066 300 × 250\2069'!important}

body#layout #AdsidebarRectangle:after{content:'300 × 250\A Medium Rectangle'!important;width:min(100%,240px)!important;aspect-ratio:300/250!important}

body#layout #AdsidebarVertical:before{content:'▧  إعلان · الشريط الجانبي الطويل   |   \2066 300 × 600\2069'!important}

body#layout #AdsidebarVertical:after{content:'300 × 600\A Half Page'!important;width:min(100%,140px)!important;aspect-ratio:1/2!important}

body#layout #Adfooter:before{content:'▧  إعلان · الفوتر   |   \2066 300 × 250\2069'!important}

body#layout #Adfooter:after{content:'300 × 250\A Medium Rectangle'!important;width:min(100%,240px)!important;aspect-ratio:300/250!important}

body#layout .tekmilo-widget-zone{--accent:#0b6bd9;--tint:#e8f3ff;--bd:#b7d5f4;border:2px dashed #7db5ec!important;background:linear-gradient(135deg,#f9fcff,#eef7ff)!important}

body#layout #TekmiloContentTools:before{content:'◫  منطقة إضافات · أعلى المحتوى   |   حتى 12 أداة'!important}

body#layout #TekmiloAfterContent:before{content:'◫  منطقة إضافات · أسفل المحتوى   |   حتى 12 أداة'!important}

body#layout #TekmiloSidebarTools:before{content:'◫  منطقة إضافات · الشريط الجانبي   |   حتى 12 أداة'!important}

body#layout #TekmiloFooterTools:before{content:'◫  منطقة إضافات · الفوتر   |   حتى 12 أداة'!important}

body#layout #Main,body#layout #Popular{--accent:#0f766e;--tint:#e5f6f2;--bd:#bfe3db;border-inline-start:5px solid #14b8a6!important}

body#layout #Main:before{content:'■  قسم أساسي · المقالات والصفحات   |   مقفل'!important}

body#layout #Popular:before{content:'■  قسم أساسي · المقالات الأكثر قراءة   |   مقفل'!important}

body#layout #Main .widget{min-height:92px!important}

body#layout #SidebarExtras{--accent:#64748b;--tint:#f1f5f9;--bd:#d5dde6;border:1px dashed #b4c1cf!important;background:#f8fafc!important;box-shadow:none!important}

body#layout #SidebarExtras:before{content:'⌛  أدوات قديمة · انقلها ثم احذفها'!important}

body#layout #SidebarExtras .widget{background:#fff!important}

@media(max-width:860px){body#layout{padding:18px 10px 70px!important}body#layout .content-layout{grid-template-columns:minmax(0,1fr)!important}body#layout .tekmilo-layout-controls:before{font-size:18px!important;padding:16px 18px!important}body#layout .section:before{font-size:11px!important;padding:0 12px!important}}

@media(max-width:1150px){.content-layout{grid-template-columns:minmax(0,1fr) 265px}.site-header{padding-inline:18px}.nav{gap:11px}.hero h1{font-size:30px}}

@media(max-width:950px){.content-layout{grid-template-columns:minmax(0,1fr) 235px}.site-header{padding:10px 15px}.nav{gap:6px 17px}.nav a{padding:10px 6px}.hero-copy{padding-left:24px}.category-card{min-height:108px}}

@media(max-width:700px){.shell{border:0}.page-padding{padding:0 10px}.site-header{min-height:59px}.hero{margin-top:10px;border-radius:12px}.hero-copy{padding:25px 20px 0}.hero h1{font-size:29px}.content-layout{display:flex;flex-direction:column}.main-column{width:100%;order:1}.sidebar{width:100%;order:2}.sidebar>.panel{width:100%}.sidebar .ad-slot{width:100%}.newsletter-footer{margin:0 10px;padding:19px}.newsletter-footer .newsletter-form{flex-direction:column}.article-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.article-grid .post-media{aspect-ratio:1.35/1}.category-grid{gap:7px}.category-card{min-height:103px}.design-preview [data-slot=sidebarVertical] .ad-placeholder{min-height:250px}}




/* ========================================================
   TEKMILO DELUXE ENHANCEMENTS (PRO EDITION)
   ======================================================== */

/* 1. MAGICAL SEARCH BUTTON AND PANEL */
.search-toggle {
  background: linear-gradient(135deg, rgba(9,104,239,0.12), rgba(6,182,212,0.15)) !important;
  border: 1px solid rgba(9,104,239,0.3) !important;
  color: var(--blue) !important;
  box-shadow: 0 0 15px rgba(9,104,239,0.15) !important;
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1) !important;
  cursor: pointer !important;
}
.search-toggle:hover {
  background: linear-gradient(135deg, #0968ef, #06b6d4) !important;
  color: #ffffff !important;
  box-shadow: 0 0 25px rgba(9,104,239,0.45) !important;
  transform: translateY(-2px) scale(1.05) !important;
}
.search-panel {
  padding: 24px 20px !important;
  background: rgba(10, 15, 24, 0.92) !important;
  backdrop-filter: blur(20px) !important;
  -webkit-backdrop-filter: blur(20px) !important;
  border-bottom: 1px solid rgba(9, 104, 239, 0.3) !important;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.5) !important;
}
html[data-theme="light"] .search-panel {
  background: rgba(255, 255, 255, 0.95) !important;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.08) !important;
  border-bottom: 1px solid rgba(0, 0, 0, 0.08) !important;
}
.search-form {
  max-width: 680px !important;
  display: flex !important;
  gap: 10px !important;
  align-items: center !important;
}
.search-input-wrapper {
  position: relative !important;
  flex: 1 !important;
}
.search-form input {
  width: 100% !important;
  height: 46px !important;
  background: var(--card) !important;
  border: 1.5px solid rgba(9, 104, 239, 0.35) !important;
  border-radius: 14px !important;
  padding: 0 16px 0 42px !important;
  color: var(--text) !important;
  font-size: 14.5px !important;
  box-shadow: 0 0 20px rgba(9, 104, 239, 0.12) !important;
  outline: none !important;
  transition: all 0.25s ease !important;
}
html[dir="rtl"] .search-form input {
  padding: 0 42px 0 16px !important;
}
.search-form input:focus {
  border-color: #06b6d4 !important;
  box-shadow: 0 0 25px rgba(6, 182, 212, 0.35) !important;
}
.search-input-icon {
  position: absolute !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  left: 14px !important;
  color: var(--blue) !important;
}
html[dir="rtl"] .search-input-icon {
  left: auto !important;
  right: 14px !important;
}
.search-submit-btn {
  height: 46px !important;
  padding: 0 22px !important;
  background: linear-gradient(135deg, #0968ef, #06b6d4) !important;
  color: #fff !important;
  border: none !important;
  border-radius: 14px !important;
  font-size: 14px !important;
  font-weight: 800 !important;
  cursor: pointer !important;
  box-shadow: 0 4px 16px rgba(9, 104, 239, 0.4) !important;
  transition: all 0.25s ease !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 6px !important;
  white-space: nowrap !important;
}
.search-submit-btn:hover {
  transform: translateY(-2px) !important;
  box-shadow: 0 6px 22px rgba(9, 104, 239, 0.55) !important;
}

/* 2. LIGHT MODE FOOTER CORRECTION */
html[data-theme="light"] .site-footer {
  background: #ffffff !important;
  color: #1e293b !important;
  border-top: 1px solid rgba(0, 0, 0, 0.08) !important;
  box-shadow: 0 -4px 25px rgba(0, 0, 0, 0.04) !important;
}
html[data-theme="light"] .site-footer .brand strong b {
  color: #0f172a !important;
}
html[data-theme="light"] .site-footer .brand small {
  color: #64748b !important;
}
html[data-theme="light"] .site-footer a {
  color: #475569 !important;
}
html[data-theme="light"] .site-footer a:hover {
  color: #0968ef !important;
}
html[data-theme="light"] .site-footer .social-links a {
  background: #f1f5f9 !important;
  color: #334155 !important;
  border: 1px solid rgba(0, 0, 0, 0.06) !important;
}
html[data-theme="light"] .site-footer .social-links a:hover {
  background: #0968ef !important;
  color: #ffffff !important;
}

/* 3. VISIBLE RESERVED ADVERTISING PLACEHOLDERS */
.ad-slot {
  display: block !important;
  margin: 22px auto !important;
  text-align: center !important;
  clear: both !important;
  max-width: 100% !important;
}
.ad-placeholder {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  background: var(--soft) !important;
  border: 1.5px dashed var(--line) !important;
  border-radius: 14px !important;
  color: var(--muted) !important;
  font-size: 13px !important;
  font-weight: 700 !important;
  padding: 18px !important;
  margin: 8px auto !important;
  box-sizing: border-box !important;
  transition: all 0.25s ease !important;
}
.ad-placeholder:hover {
  border-color: var(--blue) !important;
  background: rgba(9, 104, 239, 0.05) !important;
  color: var(--blue) !important;
}
.ad-placeholder .ad-icon {
  display: inline-block !important;
  font-size: 22px !important;
  margin-bottom: 4px !important;
}
.top-ad .ad-placeholder {
  min-height: 90px !important;
  width: 728px !important;
  max-width: 96% !important;
}
.ad-slot[data-slot="sidebarRectangle"] .ad-placeholder {
  min-height: 250px !important;
  width: 300px !important;
  max-width: 100% !important;
}
.ad-slot[data-slot="sidebarVertical"] .ad-placeholder {
  min-height: 600px !important;
  width: 300px !important;
  max-width: 100% !important;
}
.ad-slot[data-slot="mid"] .ad-placeholder,
.ad-slot[data-slot="article"] .ad-placeholder {
  min-height: 120px !important;
  width: 728px !important;
  max-width: 96% !important;
}
.ad-slot[data-slot="footer"] .ad-placeholder {
  min-height: 90px !important;
  width: 728px !important;
  max-width: 96% !important;
}

/* 4. HIGH-END CENTERED EMPTY STATE */
.empty-state {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  padding: 65px 24px !important;
  text-align: center !important;
  background: var(--card) !important;
  border: 1.5px dashed var(--line) !important;
  border-radius: 20px !important;
  margin: 50px auto !important;
  max-width: 650px !important;
  width: 100% !important;
  box-sizing: border-box !important;
  box-shadow: 0 10px 40px rgba(0,0,0,0.06) !important;
  grid-column: 1 / -1 !important;
}
.empty-state-icon {
  width: 84px !important;
  height: 84px !important;
  border-radius: 50% !important;
  background: linear-gradient(135deg, rgba(9,104,239,0.15), rgba(6,182,212,0.25)) !important;
  color: var(--blue) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  margin-bottom: 22px !important;
  box-shadow: 0 0 25px rgba(9,104,239,0.25) !important;
}
.empty-state-icon svg {
  width: 42px !important;
  height: 42px !important;
}
.empty-state h3 {
  font-size: 22px !important;
  font-weight: 800 !important;
  color: var(--text) !important;
  margin-bottom: 12px !important;
}
.empty-state p {
  font-size: 15px !important;
  color: var(--muted) !important;
  max-width: 480px !important;
  line-height: 1.8 !important;
  margin-bottom: 26px !important;
}
.empty-state .empty-btn {
  display: inline-flex !important;
  align-items: center !important;
  gap: 8px !important;
  background: linear-gradient(135deg, #0968ef, #06b6d4) !important;
  color: #fff !important;
  padding: 13px 32px !important;
  border-radius: 14px !important;
  font-weight: 800 !important;
  font-size: 15px !important;
  text-decoration: none !important;
  box-shadow: 0 6px 20px rgba(9,104,239,0.35) !important;
  transition: all 0.25s ease !important;
}
.empty-state .empty-btn:hover {
  transform: translateY(-3px) scale(1.02) !important;
  box-shadow: 0 8px 30px rgba(9,104,239,0.5) !important;
}

/* 5. POST CARD THUMBNAIL CRISP IMAGES */
.post-media {
  background: var(--soft) !important;
  position: relative !important;
  overflow: hidden !important;
}
.post-media img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  transition: transform 0.4s ease !important;
}
.post-card:hover .post-media img {
  transform: scale(1.05) !important;
}



/* [[TEKMILO_CUSTOM_CSS_START]] */
