body.script:
//

/* Tekmilo progressive enhancement. Native Blogger posts remain without JavaScript. */

(() => {

  'use strict';

  const root = document.documentElement;

  const lang = root.lang === 'en' ? 'en' : 'ar';

  const themeStorageKey = 'tekmilo-theme-v2';

  const t = (ar, en) => lang === 'en' ? en : ar;

  const $ = (selector, scope = document) => scope.querySelector(selector);

  const $$ = (selector, scope = document) => [...scope.querySelectorAll(selector)];

  const defaults = {social: [], pages: {ar: [], en: []}, newsletter: null, logo: '', navigation: {}};

  let config = defaults;

  try {

    const custom = JSON.parse($('#tekmilo-config')?.textContent || '{}');

    config = {...defaults, ...custom};

  } catch (error) { console.warn('Tekmilo: invalid configuration JSON. Optional modules remain off.', error); }

  const safeUrl = (value, sameOrigin = false) => {

    if (!value || typeof value !== 'string') return '';

    try {

      const url = new URL(value, location.origin);

      if (!['https:', 'http:'].includes(url.protocol)) return '';

      if (url.protocol !== 'https:' && url.hostname !== 'localhost' && url.hostname !== '127.0.0.1') return '';

      if (sameOrigin && url.origin !== location.origin) return '';

      return url.href;

    } catch { return ''; }

  };

  const key = value => {

    try { const u = new URL(value, location.origin); return u.pathname.replace(/\/$/, '') || '/'; }

    catch { return value; }

  };

  const remember = (name, value) => { try { localStorage.setItem(name, value); } catch { /* Private browsing. */ } };

  const themeButton = $('#theme-toggle');

  const setTheme = dark => {

    root.dataset.theme = dark ? 'dark' : 'light';

    if (themeButton) {

      themeButton.setAttribute('aria-pressed', String(dark));

      themeButton.setAttribute('aria-label', dark ? t('تفعيل الوضع النهاري', 'Switch to light mode') : t('تفعيل الوضع الليلي', 'Switch to dark mode'));

      themeButton.innerHTML = dark 
        ? `<svg class="theme-icon sun-icon" viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="5"></circle><line x1="12" y1="1" x2="12" y2="3"></line><line x1="12" y1="21" x2="12" y2="23"></line><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"></line><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"></line><line x1="1" y1="12" x2="3" y2="12"></line><line x1="21" y1="12" x2="23" y2="12"></line><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"></line><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"></line></svg>`
        : `<svg class="theme-icon moon-icon" viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"></path></svg>`;

    }

  };

  setTheme(root.dataset.theme === 'dark');

  themeButton?.addEventListener('click', () => {

    const dark = root.dataset.theme !== 'dark'; setTheme(dark); remember(themeStorageKey, dark ? 'dark' : 'light');

  });

  const menu = $('#main-navigation');

  const menuButton = $('#menu-toggle');

  const search = $('#search-panel');

  const searchButton = $('#search-toggle');

  menuButton?.addEventListener('click', () => {

    const open = menu.classList.toggle('is-open'); menuButton.setAttribute('aria-expanded', String(open));

  });

  searchButton?.addEventListener('click', () => {

    search.hidden = !search.hidden; searchButton.setAttribute('aria-expanded', String(!search.hidden));

    if (!search.hidden) $('input', search).focus();

  });

  document.addEventListener('keydown', event => {

    if (event.key !== 'Escape') return;

    if (search && !search.hidden) { search.hidden = true; searchButton.setAttribute('aria-expanded', 'false'); searchButton.focus(); }

    if (menu?.classList.contains('is-open')) { menu.classList.remove('is-open'); menuButton.setAttribute('aria-expanded', 'false'); menuButton.focus(); }

  });

  // Native form submits a real language-scoped Blogger query, including with JS disabled.

  $('#site-search')?.addEventListener('submit', event => {

    const input = $('input[name=q]', event.currentTarget);

    const query = input.value.replace(/(?:^|\s)label:[^\s]+/gi, '').trim();

    input.value = `label:${lang}${query ? ' ' + query : ''}`;

  });

  // Bulletproof Language Switching Engine
function handleThemeLanguageToggle(e) {
  if (e) e.preventDefault();
  const path = window.location.pathname.toLowerCase();
  const search = window.location.search;
  const isEn = (document.documentElement.lang === 'en') || path.includes('/search/label/en') || search.includes('hl=en') || search.includes('lang=en');
  if (isEn) {
    localStorage.setItem('tekmilo_user_lang', 'ar');
    window.location.href = window.location.origin + '/?hl=ar';
  } else {
    localStorage.setItem('tekmilo_user_lang', 'en');
    window.location.href = window.location.origin + '/search/label/en?hl=en';
  }
  return false;
}
window.handleThemeLanguageToggle = handleThemeLanguageToggle;

(function syncThemeLanguageState() {
  const urlParams = new URLSearchParams(window.location.search);
  const path = window.location.pathname.toLowerCase();
  const isEnUrl = path.includes('/search/label/en') || urlParams.get('hl') === 'en' || urlParams.get('lang') === 'en';
  const isArUrl = path.includes('/search/label/ar') || urlParams.get('hl') === 'ar' || urlParams.get('lang') === 'ar' || (path === '/' && urlParams.get('hl') !== 'en');

  let activeLang = 'ar';
  if (isEnUrl) {
    activeLang = 'en';
    localStorage.setItem('tekmilo_user_lang', 'en');
  } else if (isArUrl) {
    activeLang = 'ar';
    localStorage.setItem('tekmilo_user_lang', 'ar');
  } else if (localStorage.getItem('tekmilo_user_lang') === 'en') {
    activeLang = 'en';
  }

  if (activeLang === 'en') {
    document.documentElement.lang = 'en';
    document.documentElement.dir = 'ltr';
    const switchBtn = document.getElementById('language-switch');
    if (switchBtn) {
      switchBtn.href = window.location.origin + '/?hl=ar';
      switchBtn.title = 'التبديل إلى العربية / Switch to Arabic';
      const labelSpan = switchBtn.querySelector('span');
      if (labelSpan) labelSpan.textContent = 'العربية';
    }
  } else {
    document.documentElement.lang = 'ar';
    document.documentElement.dir = 'rtl';
    const switchBtn = document.getElementById('language-switch');
    if (switchBtn) {
      switchBtn.href = window.location.origin + '/search/label/en?hl=en';
      switchBtn.title = 'Switch to English / التبديل للإنجليزية';
      const labelSpan = switchBtn.querySelector('span');
      if (labelSpan) labelSpan.textContent = 'English';
    }
  }
})();

const languageLink = $('#language-switch');

  const alternate = $(`link[rel=alternate][hreflang="${lang === 'en' ? 'ar' : 'en'}"]`);

  if (alternate && languageLink) languageLink.href = alternate.href;

  languageLink?.addEventListener('click', () => remember('tekmilo-language', lang === 'en' ? 'ar' : 'en'));

  // URL always wins over stored preference: no automatic redirects of indexable content.

  remember('tekmilo-language', lang);

  $$('.translation-link').forEach(link => {

    if (alternate) { link.href = alternate.href; link.hidden = false; }

  });

  if (safeUrl(config.logo)) $$('.brand-mark').forEach(mark => {

    const img = document.createElement('img'); img.src = safeUrl(config.logo); img.alt = 'Tekmilo | تيكميلو';

    img.width = 43; img.height = 49; img.className = 'brand-mark'; mark.replaceWith(img);

  });

  for (const [name, value] of Object.entries(config.navigation?.[lang] || {})) {

    const url = safeUrl(value, true);

    if (url) $$('[data-nav]').filter(a => a.dataset.nav === name).forEach(a => { a.href = url; });

  }

  const pageLinks = Array.isArray(config.pages?.[lang]) ? config.pages[lang] : [];

  $$('.configured-pages').forEach(container => {

    pageLinks.forEach(page => {

      const url = safeUrl(page.url, true); if (!url || !page.title) return;

      const a = document.createElement('a'); a.href = url; a.textContent = page.title; container.append(a);

      if (page.kind === 'about') $$('.about-link').forEach(link => { link.href = url; });

    });

  });

  const social = Array.isArray(config.social) ? config.social : [];

  $$('.social-links').forEach(container => {

    social.forEach(item => {

      const url = safeUrl(item.url); if (!url || !item.name) return;

      const a = document.createElement('a'); a.href = url; a.textContent = item.short || item.name;

      a.setAttribute('aria-label', item.name); a.rel = 'me noopener'; a.target = '_blank'; container.append(a);

    });

    if (container.children.length) { container.hidden = false; container.closest('.social-panel')?.removeAttribute('hidden'); }

  });

  const newsletter = config.newsletter;

  if (newsletter && safeUrl(newsletter.action) && /^https:/.test(newsletter.action) && newsletter.emailField) {

    $$('.newsletter').forEach(module => {

      const form = $('.newsletter-form', module); form.action = safeUrl(newsletter.action); form.method = 'post';

      const email = $('input[type=email]', form); email.name = String(newsletter.emailField);

      for (const [name, value] of Object.entries(newsletter.fields || {})) {

        const input = document.createElement('input'); input.type = 'hidden'; input.name = name; input.value = String(value); form.append(input);

      }

      if (newsletter.honeypot) {

        const trap = document.createElement('input'); trap.name = String(newsletter.honeypot); trap.type = 'text';

        trap.className = 'sr-only'; trap.tabIndex = -1; trap.autocomplete = 'off'; trap.setAttribute('aria-hidden', 'true'); form.append(trap);

      }

      // Browser validation then provider-hosted confirmation/errors. Never synthesize success.

      form.addEventListener('submit', event => {

