  $$('.ad-slot').forEach(slot => {

    const template = $('template.ad-template', slot);

    // Each numbered Layout gadget owns its placement: adding code publishes it,

    // while clearing the gadget returns the reserved space to its clean state.

    if (!template?.content.textContent.trim() && !template?.content.querySelector('img,iframe,ins,script')) return;

    // Remove scripts while the fragment is inert. Appending scripts inside a cloned

    // template and then replacing them can execute inline network code twice.

    const fragment = template.content.cloneNode(true);

    const scripts = $$('script', fragment);

    scripts.forEach(script => script.remove());

    const content = document.createElement('div'); content.className = 'ad-content';

    content.append(fragment); slot.append(content);

    scripts.forEach(inert => {

      const script = document.createElement('script');

      for (const attribute of inert.attributes) script.setAttribute(attribute.name, attribute.value);

      if (inert.src) {

        if (loadedScripts.has(inert.src)) { inert.remove(); return; }

        loadedScripts.add(inert.src);

        script.async = false;

      }

      script.textContent = inert.textContent;

      content.append(script);

    });

  });


