  window.getPostCover = function(title, existingImage) {
    if (existingImage && !existingImage.includes('fallback') && !existingImage.includes('transparent') && existingImage.startsWith('http') && !existingImage.includes('photo-1677442136019-21780efad99a')) {
      return existingImage
        .replace(/\/s[0-9]+(-c)?\//, '/w1200-h630-c/')
        .replace(/\/w[0-9]+-h[0-9]+(-c)?\//, '/w1200-h630-c/');
    }
    const lower = (title || '').toLowerCase();
    for (const [key, imgUrl] of Object.entries(window.postImageMap)) {
      if (lower.includes(key)) return imgUrl;
    }
    if (title && title.length) {
      let hash = 0;
      for (let i = 0; i < title.length; i++) {
        hash = ((hash << 5) - hash) + title.charCodeAt(i);
        hash |= 0;
      }
      const idx = Math.abs(hash) % window.curatedTechCovers.length;
      return window.curatedTechCovers[idx];
    }
    return window.curatedTechCovers[0];
  };

  window.handleCardImgError = function(img, title) {
    img.onerror = null;
    if (title) {
      let hash = 1;
      for (let i = 0; i < title.length; i++) {
        hash = ((hash << 5) - hash) + title.charCodeAt(i);
        hash |= 0;
      }
      const nextIdx = (Math.abs(hash) + 1) % window.curatedTechCovers.length;
      img.src = window.curatedTechCovers[nextIdx];
    } else {
      img.src = window.curatedTechCovers[0];
    }
  };
