  const cache = new Map();

  const parseFeed = xml => {

    const doc = new DOMParser().parseFromString(xml, 'application/xml');

    if (doc.querySelector('parsererror')) throw new Error('Invalid Atom feed');

    const ns = 'http://www.w3.org/2005/Atom';

    const text = (entry, name) => entry.getElementsByTagNameNS(ns, name)[0]?.textContent || '';

    return [...doc.getElementsByTagNameNS(ns, 'entry')].map(entry => {

      const labels = [...entry.getElementsByTagNameNS(ns, 'category')].map(node => node.getAttribute('term'));

      const url = [...entry.getElementsByTagNameNS(ns, 'link')].find(node => node.getAttribute('rel') === 'alternate')?.getAttribute('href') || '';

      const body = new DOMParser().parseFromString(text(entry, 'content') || text(entry, 'summary'), 'text/html');

      const thumb = entry.getElementsByTagNameNS('http://search.yahoo.com/mrss/', 'thumbnail')[0]?.getAttribute('url') || body.querySelector('img')?.getAttribute('src') || '';

      body.querySelectorAll('script,style').forEach(node => node.remove());

      return {url: safeUrl(url, true), title: text(entry, 'title'), labels, image: safeUrl(thumb),

        excerpt: (body.body.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 170),

        published: text(entry, 'published'), updated: text(entry, 'updated')};

    }).filter(post => {

      if (!post.url || !post.title || post.labels.includes(lang === 'en' ? 'ar' : 'en')) return false;

      return true; // Show all posts on homepage

