  const getFeed = (label, max = 30) => {

    const path = label ? `/feeds/posts/default/-/${encodeURIComponent(label)}?alt=atom&max-results=${max}` : `/feeds/posts/default?alt=atom&max-results=${max}`;

    if (!cache.has(path)) cache.set(path, (async () => {

      const controller = new AbortController(); const timeout = setTimeout(() => controller.abort(), 9000);

      try {

        const response = await fetch(path, {signal: controller.signal, credentials: 'same-origin'});

        if (!response.ok) throw new Error(`Feed HTTP ${response.status}`);

        return parseFeed(await response.text());

      } finally { clearTimeout(timeout); }

    })());

    return cache.get(path);

  };

