      const featuredSource = featuredResult.status === 'fulfilled' && featuredResult.value.length ? featuredResult.value : latestFeed;

      const reviewsSource = reviewsResult.status === 'fulfilled' && reviewsResult.value.length ? reviewsResult.value : latestFeed;

