                  <a href="/">${isAr ? 'الرئيسية' : 'Home'}</a> <span>/</span> <span>${title}</span>
                </nav>
                <h1 class="article-title">${title}</h1>
                <div class="article-info">
                  <time>${pubDate}</time>
                </div>
                <img class="article-cover" src="${(window.getPostCover ? window.getPostCover(title, '') : '')}" alt="${title}" loading="eager" decoding="async" />
                <div class="article-body">${bodyHtml}</div>
                <div class="share-bar">
                  <strong>${isAr ? 'شارك المقال' : 'Share this article'}</strong>
                  <button id="copy-link" type="button">${isAr ? 'نسخ الرابط' : 'Copy link'}</button>
                  <span id="share-status" role="status" style="margin-right:10px;color:var(--blue);font-weight:700;"></span>
                </div>
              `;

              const copyBtn = articleElem.querySelector('#copy-link');
              if (copyBtn) {
                copyBtn.onclick = () => {
                  navigator.clipboard.writeText(location.href);
                  const st = articleElem.querySelector('#share-status');
                  if (st) st.textContent = isAr ? 'تم نسخ الرابط!' : 'Link copied!';
                };
              }
            }
          }).catch(e => console.error('Article loader error:', e));
      }
    }
  }


  // Ensure all native post cards and article covers have active high-res images
  try {
    document.querySelectorAll('.post-card').forEach(function(card) {
      var heading = card.querySelector('h3');
      var title = heading ? heading.textContent : '';
      var img = card.querySelector('.post-media img');
      if (img) {
        if (!img.src || img.src.includes('photo-1677442136019-21780efad99a') || img.src.includes('photo-1518770660439-4636190af475')) {
          img.src = getPostCover(title, img.src);
        }
      }
    });
    var artCover = document.querySelector('.article-cover');
    var artTitle = document.querySelector('.article-title');
    if (artCover && artTitle) {
      if (!artCover.src || artCover.src.includes('photo-1677442136019-21780efad99a')) {
        artCover.src = getPostCover(artTitle.textContent, '');
      }
    }
  } catch(e) {}
// Dynamic Favicon Enforcer: overrides default Blogger favicon
  try {
    var customFaviconUri = 'data:image/png;base64,';
    if (customFaviconUri) {
      var existingFavicons = document.querySelectorAll("link[rel*='icon'], link[rel='apple-touch-icon']");
      existingFavicons.forEach(function(el) { el.remove(); });
      var fLink = document.createElement('link');
      fLink.type = 'image/png';
      fLink.rel = 'shortcut icon';
      fLink.href = customFaviconUri;
      document.head.appendChild(fLink);
      var fApple = document.createElement('link');
      fApple.rel = 'apple-touch-icon';
      fApple.href = customFaviconUri;
      document.head.appendChild(fApple);
    }
  } catch(e) {}
//
